import { BeautifulUIRoot } from "../beautiful-ui/BeautifulUIRoot";

export type RecordsTableProps = NonNullable<ComponentProps<typeof LegacyRecordsTable>>;

export const RecordsTable = forwardRef<HTMLDivElement, RecordsTableProps>((props, ref) => (
  <BeautifulUIRoot ref={ref}>
    <LegacyRecordsTable {...props} />
  </BeautifulUIRoot>
));

RecordsTable.displayName = "RecordsTable";

export default RecordsTable;

