export default function RecordsTable({
  rows = INITIAL_ROWS,
  fill = false,
  onSelectionChange,
  onSortChange,
  onAddCalculation,
}: RecordsTableProps = {}) {
  const shape = useShape();
  const shapeStyle = {
    "--records-container-radius": `${shape.containerRadius}px`,
    "--records-control-radius": `${shape.bgRadius}px`,
    "--records-chip-radius": `${shape.bgRadius}px`,
    "--records-checkbox-radius": shape.variant === "pill" ? "6px" : "4px",
    // Menu rows sit 6px inside their panel; the editor is inset by 12px.
    "--records-menu-item-radius": `${nestedRadius(shape.containerRadius, 6)}px`,
    "--records-inset-radius": `${nestedRadius(shape.containerRadius, 12)}px`,
  } as CSSProperties;
  const hoverRef = useRef<HTMLDivElement>(null);
  const hover = useFluidHover(hoverRef, { gapClick: false });
  const { setActiveIndex } = hover;
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [sort, setSort] = useState<{ key: SortKey; dir: 1 | -1 }>({ key: "name", dir: 1 });
  const [columnWidths, setColumnWidths] = useState(DEFAULT_COLUMN_WIDTHS);
  const [actionColumnWidth, setActionColumnWidth] = useState(100);
  const [columnWidthsLocked, setColumnWidthsLocked] = useState(false);
  const [resizingColumn, setResizingColumn] = useState<ColumnKey | null>(null);
  const initialColumnWidthsRef = useRef<Record<ColumnKey, number> | null>(null);
  const tableRef = useRef<HTMLTableElement>(null);
  const resizeCleanupRef = useRef<(() => void) | null>(null);

  /* property popover, anchored to the clicked header */
  const [prop, setProp] = useState<{ col: string; x: number; y: number } | null>(null);
  const propTriggerRef = useRef<HTMLElement | null>(null);
  const propPopoverRef = useRef<HTMLDivElement>(null);
  const [grounding, setGrounding] = useState(false);
  const [groundingHelpOpen, setGroundingHelpOpen] = useState(false);
  const [configMenu, setConfigMenu] = useState<"type" | "tool" | "inputs" | null>(null);
  const [columnOverrides, setColumnOverrides] = useState<Record<string, Partial<ColumnMeta>>>({});
  const [inputSelections, setInputSelections] = useState<Record<string, string[]>>({});
  const [pinnedColumns, setPinnedColumns] = useState<Set<string>>(new Set());
  const [moreSettingsOpen, setMoreSettingsOpen] = useState(false);
  const [advancedSettings, setAdvancedSettings] = useState({
    required: false,
    allowEmpty: true,
    confidence: false,
  });
  /* + new-property menu */
  const [addOpen, setAddOpen] = useState<{ x: number; y: number } | null>(null);
  const [tableMenuOpen, setTableMenuOpen] = useState<{ x: number; y: number } | null>(null);
  /* the added AI column and its lifecycle */
  const [aiAdded, setAiAdded] = useState(false);
  const [aiDone, setAiDone] = useState(false);
  const [pendingOpenAi, setPendingOpenAi] = useState(false);
  const aiThRef = useRef<HTMLTableCellElement>(null);
  /* programmatic scrolls (revealing the new column) shouldn't close popovers */
  const ignoreScrollRef = useRef(false);
  /* a running calculation resolves rows one by one */
  const [calc, setCalc] = useState<{ col: string; resolved: number } | null>(null);

  const closePropertyPopover = useCallback((restoreFocus = false) => {
    setProp(null);
    setConfigMenu(null);
    setGroundingHelpOpen(false);
    setMoreSettingsOpen(false);
    if (restoreFocus) requestAnimationFrame(() => propTriggerRef.current?.focus());
  }, []);

  useEffect(() => {
    if (!prop) return;
    requestAnimationFrame(() => {
      propPopoverRef.current
        ?.querySelector<HTMLElement>("button:not(:disabled), input:not(:disabled), [tabindex='0']")
        ?.focus();
    });
  }, [prop]);

  useEffect(() => {
    if (!prop) return;
    const closeOnViewportChange = () => closePropertyPopover();
    window.addEventListener("resize", closeOnViewportChange);
    window.addEventListener("scroll", closeOnViewportChange);
    return () => {
      window.removeEventListener("resize", closeOnViewportChange);
      window.removeEventListener("scroll", closeOnViewportChange);
    };
  }, [prop, closePropertyPopover]);

  useEffect(
    () => () => {
      resizeCleanupRef.current?.();
    },
    [],
  );

  /* Let the table fill its available space once, then capture those rendered
   * widths before paint. From that point on every column is explicit, so a
   * resize changes only the dragged column and the table's total width. */
  useLayoutEffect(() => {
    if (columnWidthsLocked || !tableRef.current) return;
    const headers = Array.from(tableRef.current.querySelectorAll<HTMLTableCellElement>("thead th"));
    if (headers.length < 6) return;

    const measured: Record<ColumnKey, number> = {
      company: headers[0].getBoundingClientRect().width,
      categories: headers[1].getBoundingClientRect().width,
      last: headers[2].getBoundingClientRect().width,
      strength: headers[3].getBoundingClientRect().width,
      links: headers[4].getBoundingClientRect().width,
      ai: DEFAULT_COLUMN_WIDTHS.ai,
    };
    initialColumnWidthsRef.current = measured;
    setColumnWidths(measured);
    setActionColumnWidth(headers[headers.length - 1].getBoundingClientRect().width);
    setColumnWidthsLocked(true);
  }, [columnWidthsLocked]);

  const visibleRows = useMemo(() => {
    return [...rows].sort((a, b) => {
      const value =
        sort.key === "name"
          ? a.name.localeCompare(b.name)
          : sort.key === "last"
            ? a.last.localeCompare(b.last)
            : STRENGTH[a.strength].rank - STRENGTH[b.strength].rank;
      return value * sort.dir;
    });
  }, [rows, sort]);

  useEffect(() => {
    setActiveIndex(null);
  }, [visibleRows, setActiveIndex]);

  /* stagger: one row resolves every beat */
  useEffect(() => {
    if (!calc) return;
    if (calc.resolved > visibleRows.length) {
      if (calc.col === AI_LABEL) setAiDone(true);
      setCalc(null);
      return;
    }
    const t = setTimeout(
      () =>
        setCalc((current) => (current ? { ...current, resolved: current.resolved + 1 } : current)),
      110,
    );
    return () => clearTimeout(t);
  }, [calc, visibleRows.length]);

  /* after adding the AI column, scroll it into view and open its config
   * anchored to the new header */
  useEffect(() => {
    if (!pendingOpenAi || !aiThRef.current) return;
    const scroller = aiThRef.current.closest(".records-scroll");
    if (scroller) {
      ignoreScrollRef.current = true;
      scroller.scrollLeft = scroller.scrollWidth;
    }
    const rect = aiThRef.current.getBoundingClientRect();
    const position = getPropertyPopoverPosition(rect, window.innerWidth);
    setProp({
      col: AI_LABEL,
      ...position,
    });
    setPendingOpenAi(false);
  }, [pendingOpenAi, aiAdded]);

  /* click anywhere else closes popovers */
  useEffect(() => {
    if (!prop && !addOpen && !tableMenuOpen) return;
    const close = (event: PointerEvent) => {
      if (!(event.target as Element).closest("[data-recpop]")) {
        closePropertyPopover();
        setAddOpen(null);
        setTableMenuOpen(null);
      }
    };
    document.addEventListener("pointerdown", close);
    return () => document.removeEventListener("pointerdown", close);
  }, [prop, addOpen, tableMenuOpen, closePropertyPopover]);

  const openProp = (col: string) => (event: React.MouseEvent) => {
    const th = (event.currentTarget as Element).closest("th");
    if (!th) return;
    setAddOpen(null);
    setTableMenuOpen(null);
    setConfigMenu(null);
    setGroundingHelpOpen(false);
    setMoreSettingsOpen(false);
    propTriggerRef.current = event.currentTarget as HTMLElement;
    setProp((current) => {
      if (current?.col === col) {
        requestAnimationFrame(() => propTriggerRef.current?.focus());
        return null;
      }
      const rect = th.getBoundingClientRect();
      const position = getPropertyPopoverPosition(rect, window.innerWidth);
      return {
        col,
        ...position,
      };
    });
  };

  const isCalc = (col: string, index: number) =>
    !!calc && calc.col === col && index >= calc.resolved;

  const allSelected = visibleRows.length > 0 && visibleRows.every((row) => selected.has(row.id));
  const partiallySelected = !allSelected && visibleRows.some((row) => selected.has(row.id));

  const toggleSort = (key: SortKey) =>
    setSort((current) => {
      const next =
        current.key === key ? { key, dir: (current.dir * -1) as 1 | -1 } : { key, dir: 1 as const };
      onSortChange?.({
        key: next.key,
        direction: next.dir === 1 ? "ascending" : "descending",
      });
      return next;
    });
  const resizeColumnBy = (key: ColumnKey, delta: number, minWidth = 120) =>
    setColumnWidths((current) => ({
      ...current,
      [key]: Math.max(minWidth, Math.min(800, current[key] + delta)),
    }));
  const startColumnResize =
    (key: ColumnKey, minWidth = 120) =>
    (event: React.PointerEvent<HTMLSpanElement>) => {
      event.preventDefault();
      event.stopPropagation();
      setProp(null);
      setConfigMenu(null);
      setGroundingHelpOpen(false);
      setMoreSettingsOpen(false);
      setAddOpen(null);
      setTableMenuOpen(null);
      resizeCleanupRef.current?.();

      const startX = event.clientX;
      const startWidth = columnWidths[key];
      const previousCursor = document.body.style.cursor;
      const previousSelection = document.body.style.userSelect;
      document.body.style.cursor = "col-resize";
      document.body.style.userSelect = "none";
      setResizingColumn(key);

      const move = (moveEvent: PointerEvent) => {
        const width = Math.max(minWidth, startWidth + moveEvent.clientX - startX);
        setColumnWidths((current) => ({ ...current, [key]: width }));
      };
      const finish = () => {
        window.removeEventListener("pointermove", move);
        window.removeEventListener("pointerup", finish);
        window.removeEventListener("pointercancel", finish);
        document.body.style.cursor = previousCursor;
        document.body.style.userSelect = previousSelection;
        setResizingColumn(null);
        resizeCleanupRef.current = null;
      };

      resizeCleanupRef.current = finish;
      window.addEventListener("pointermove", move);
      window.addEventListener("pointerup", finish);
      window.addEventListener("pointercancel", finish);
    };
  const toggleRow = (id: string) =>
    setSelected((current) => {
      const next = new Set(current);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      onSelectionChange?.([...next]);
      return next;
    });
  const toggleAll = () =>
    setSelected((current) => {
      const next = new Set(current);
      if (allSelected) visibleRows.forEach((row) => next.delete(row.id));
      else visibleRows.forEach((row) => next.add(row.id));
      onSelectionChange?.([...next]);
      return next;
    });

  const meta = prop ? { ...COLUMN_META[prop.col], ...columnOverrides[prop.col] } : null;
  const selectedInputs =
    prop && meta ? (inputSelections[prop.col] ?? (meta.inputs ? [meta.inputs] : [])) : [];
  const tableWidth =
    columnWidths.company +
    columnWidths.categories +
    columnWidths.last +
    columnWidths.strength +
    columnWidths.links +
    (aiAdded ? columnWidths.ai : 0) +
    actionColumnWidth;
  const hoverRect =
    hover.isMeasured && hover.activeIndex !== null
      ? (hover.itemRects[hover.activeIndex] ?? null)
      : null;

  return (
    <div
      className={`records-shell${fill ? " is-fill" : ""}`}
      style={{
        ...shapeStyle,
        borderRadius: fill ? 0 : shape.variant === "pill" ? shape.bgRadius : shape.containerRadius,
      }}
    >
      <p className="sr-only" aria-live="polite">
        {calc
          ? `Calculating ${calc.col}: ${Math.min(calc.resolved, visibleRows.length)} of ${visibleRows.length} rows complete`
          : `${selected.size} companies selected`}
      </p>
      <div
        className="records-scroll"
        tabIndex={0}
        aria-label="Companies table. Scroll horizontally and vertically to view all columns and records."
        onScroll={() => {
          setActiveIndex(null);
          if (ignoreScrollRef.current) {
            ignoreScrollRef.current = false;
            return;
          }
          setProp(null);
          setConfigMenu(null);
          setGroundingHelpOpen(false);
          setMoreSettingsOpen(false);
          setAddOpen(null);
          setTableMenuOpen(null);
        }}
      >
        <div
          ref={hoverRef}
          className="records-grid"
          style={{ width: columnWidthsLocked ? tableWidth : "100%", minWidth: tableWidth }}
          {...hover.handlers}
        >
          <FluidHoverHighlight hover={hover} className="z-0" />
          {/* The opaque pinned-column plane blocks scrolled cells underneath it.
              Both highlights share the same row target and spring. */}
          <div
            aria-hidden="true"
            className="records-pinned-hover"
            style={{ width: columnWidths.company }}
          >
            <FluidHoverHighlight
              rect={hoverRect ? { ...hoverRect, left: 0, width: columnWidths.company } : null}
              session={hover.sessionRef.current}
            />
          </div>
          <table
            ref={tableRef}
            className="records-table"
            style={{ width: columnWidthsLocked ? tableWidth : "100%", minWidth: tableWidth }}
          >
            <caption className="sr-only">
              Company records with sortable and keyboard-resizable property columns
            </caption>
            <colgroup>
              <col className="records-company-col" style={{ width: columnWidths.company }} />
              <col className="records-category-col" style={{ width: columnWidths.categories }} />
              <col className="records-last-col" style={{ width: columnWidths.last }} />
              <col className="records-strength-col" style={{ width: columnWidths.strength }} />
              <col className="records-link-col" style={{ width: columnWidths.links }} />
              {aiAdded && <col style={{ width: columnWidths.ai }} />}
              <col style={{ width: 100 }} />
            </colgroup>
            <thead>
              <tr>
                <th
                  className={`records-header-cell records-sticky-cell ${prop?.col === "Company" ? "is-colsel" : ""}`}
                >
                  <div className="records-company-header">
                    <Checkbox
                      checked={allSelected}
                      mixed={partiallySelected}
                      onChange={toggleAll}
                      label="Select all companies"
                    />
                    <button
                      type="button"
                      className="flex h-8 min-w-0 flex-1 items-center text-left"
                      onClick={openProp("Company")}
                    >
                      <span>Company</span>
                    </button>
                  </div>
                  <span
                    role="separator"
                    tabIndex={0}
                    aria-orientation="vertical"
                    aria-label="Resize Company column"
                    aria-valuemin={180}
                    aria-valuemax={800}
                    aria-valuenow={Math.round(columnWidths.company)}
                    className={`records-resize-handle ${resizingColumn === "company" ? "is-resizing" : ""}`}
                    onPointerDown={startColumnResize("company", 180)}
                    onKeyDown={(event) => {
                      if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") return;
                      event.preventDefault();
                      event.stopPropagation();
                      resizeColumnBy("company", event.key === "ArrowRight" ? 12 : -12, 180);
                    }}
                  />
                </th>
                <HeaderCell
                  label="Categories"
                  selected={prop?.col === "Categories"}
                  onPick={openProp("Categories")}
                  sort={sort}
                  onSort={toggleSort}
                  onResizeStart={startColumnResize("categories")}
                  onResizeBy={(delta) => resizeColumnBy("categories", delta)}
                  width={columnWidths.categories}
                  resizing={resizingColumn === "categories"}
                  icon={<Icon size={15}>{TYPE_GLYPHS["Multi select"]}</Icon>}
                />
                <HeaderCell
                  label="Last interaction"
                  selected={prop?.col === "Last interaction"}
                  onPick={openProp("Last interaction")}
                  sortKey="last"
                  sort={sort}
                  onSort={toggleSort}
                  onResizeStart={startColumnResize("last")}
                  onResizeBy={(delta) => resizeColumnBy("last", delta)}
                  width={columnWidths.last}
                  resizing={resizingColumn === "last"}
                  icon={<Icon size={15}>{TYPE_GLYPHS.Date}</Icon>}
                />
                <HeaderCell
                  label="Connection strength"
                  selected={prop?.col === "Connection strength"}
                  onPick={openProp("Connection strength")}
                  sortKey="strength"
                  sort={sort}
                  onSort={toggleSort}
                  onResizeStart={startColumnResize("strength")}
                  onResizeBy={(delta) => resizeColumnBy("strength", delta)}
                  width={columnWidths.strength}
                  resizing={resizingColumn === "strength"}
                  icon={<Icon size={15}>{TYPE_GLYPHS["Single select"]}</Icon>}
                />
                <HeaderCell
                  label="Links"
                  selected={prop?.col === "Links"}
                  onPick={openProp("Links")}
                  sort={sort}
                  onSort={toggleSort}
                  onResizeStart={startColumnResize("links")}
                  onResizeBy={(delta) => resizeColumnBy("links", delta)}
                  width={columnWidths.links}
                  resizing={resizingColumn === "links"}
                  icon={<Icon size={15}>{TYPE_GLYPHS.URL}</Icon>}
                />
                {aiAdded && (
                  <th
                    ref={aiThRef}
                    className={`records-header-cell ${prop?.col === AI_LABEL ? "is-colsel" : ""}`}
                  >
                    <button
                      type="button"
                      className="records-header-button"
                      onClick={openProp(AI_LABEL)}
                    >
                      <span className="records-header-icon">
                        <Icon size={15}>{TYPE_GLYPHS.Text}</Icon>
                      </span>
                      <span className="truncate">{AI_LABEL}</span>
                    </button>
                    <span
                      role="separator"
                      tabIndex={0}
                      aria-orientation="vertical"
                      aria-label={`Resize ${AI_LABEL} column`}
                      aria-valuemin={120}
                      aria-valuemax={800}
                      aria-valuenow={Math.round(columnWidths.ai)}
                      className={`records-resize-handle ${resizingColumn === "ai" ? "is-resizing" : ""}`}
                      onPointerDown={startColumnResize("ai")}
                      onKeyDown={(event) => {
                        if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") return;
                        event.preventDefault();
                        event.stopPropagation();
                        resizeColumnBy("ai", event.key === "ArrowRight" ? 12 : -12);
                      }}
                    />
                  </th>
                )}
                <th className="records-header-cell">
                  <div className="flex h-[35px] items-center gap-1 px-2">
                    <button
                      type="button"
                      aria-label="New property"
                      data-recpop
                      onClick={(event) => {
                        setProp(null);
                        setTableMenuOpen(null);
                        const rect = (event.currentTarget as Element).getBoundingClientRect();
                        setAddOpen((current) =>
                          current
                            ? null
                            : {
                                x: Math.min(rect.left, window.innerWidth - 276),
                                y: rect.bottom + 6,
                              },
                        );
                      }}
                      className="flex size-7 items-center justify-center rounded-[var(--records-control-radius)] text-[var(--ink-2)] transition-colors duration-80 hover:bg-[var(--hover)] hover:text-[var(--ink)]"
                    >
                      <Icon size={15} strokeWidth={2}>
                        <path d="M12 5v14M5 12h14" />
                      </Icon>
                    </button>
                    <button
                      type="button"
                      aria-label="Table options"
                      aria-expanded={!!tableMenuOpen}
                      data-recpop
                      onClick={(event) => {
                        setProp(null);
                        setAddOpen(null);
                        const rect = event.currentTarget.getBoundingClientRect();
                        setTableMenuOpen((current) =>
                          current
                            ? null
                            : {
                                x: Math.max(8, Math.min(rect.right - 220, window.innerWidth - 228)),
                                y: rect.bottom + 6,
                              },
                        );
                      }}
                      className="flex size-7 items-center justify-center rounded-[var(--records-control-radius)] text-[var(--ink-3)] transition-colors duration-80 hover:bg-[var(--hover)] hover:text-[var(--ink)]"
                    >
                      <svg
                        width="15"
                        height="15"
                        viewBox="0 0 24 24"
                        fill="currentColor"
                        aria-hidden
                      >
                        <circle cx="5" cy="12" r="1.6" />
                        <circle cx="12" cy="12" r="1.6" />
                        <circle cx="19" cy="12" r="1.6" />
                      </svg>
                    </button>
                  </div>
                </th>
              </tr>
            </thead>
            {/* data cells stay silent — the papery link/flick sound is too much when scanning rows */}
            <tbody data-cuelume-silent>
              {visibleRows.map((row, index) => {
                const selectedRow = selected.has(row.id);
                const strength = STRENGTH[row.strength];
                return (
                  <RecordsHoverRow
                    key={row.id}
                    index={index}
                    selected={selectedRow}
                    registerItem={hover.registerItem}
                  >
                    <td
                      className={`records-cell records-sticky-cell records-company-cell ${prop?.col === "Company" ? "is-colsel" : ""}`}
                    >
                      <span className="records-rownum">{index + 1}</span>
                      <Checkbox
                        checked={selectedRow}
                        onChange={() => toggleRow(row.id)}
                        label={`Select ${row.name}`}
                      />
                      <span className="records-company-mark">
                        {row.name.slice(0, 1).toUpperCase()}
                      </span>
                      {row.website ? (
                        <a
                          href={`https://${row.website}`}
                          title={row.name}
                          className="records-company-name has-link"
                        >
                          {row.name}
                        </a>
                      ) : (
                        <span title={row.name} className="records-company-name">
                          {row.name}
                        </span>
                      )}
                    </td>
                    <td className={`records-cell ${prop?.col === "Categories" ? "is-colsel" : ""}`}>
                      {isCalc("Categories", index) ? <CalcCell /> : <TagList tags={row.tags} />}
                    </td>
                    <td
                      className={`records-cell ${row.last === "No contact" ? "records-muted" : ""} ${prop?.col === "Last interaction" ? "is-colsel" : ""}`}
                    >
                      {isCalc("Last interaction", index) ? <CalcCell /> : row.last}
                    </td>
                    <td
                      className={`records-cell ${prop?.col === "Connection strength" ? "is-colsel" : ""}`}
                    >
                      {isCalc("Connection strength", index) ? (
                        <CalcCell />
                      ) : (
                        <span className="records-strength">
                          <span
                            className="records-strength-dot"
                            style={{ background: strength.color }}
                          />
                          {strength.label}
                        </span>
                      )}
                    </td>
                    <td className={`records-cell ${prop?.col === "Links" ? "is-colsel" : ""}`}>
                      {isCalc("Links", index) ? (
                        <CalcCell />
                      ) : row.website ? (
                        <a
                          className="records-link"
                          href={`https://${row.website}`}
                          title={row.website}
                          target="_blank"
                          rel="noreferrer"
                        >
                          <span className="records-link-label">{row.website}</span>
                          <Icon size={12}>
                            <path d="M14 5h5v5M19 5l-8 8" />
                          </Icon>
                        </a>
                      ) : (
                        <span className="records-muted">—</span>
                      )}
                    </td>
                    {aiAdded && (
                      <td className={`records-cell ${prop?.col === AI_LABEL ? "is-colsel" : ""}`}>
                        {calc?.col === AI_LABEL ? (
                          index < calc.resolved ? (
                            competitorsFor(index)
                          ) : (
                            <CalcCell />
                          )
                        ) : aiDone ? (
                          competitorsFor(index)
                        ) : (
                          <span className="records-muted">—</span>
                        )}
                      </td>
                    )}
                    <td className="records-cell" />
                  </RecordsHoverRow>
                );
              })}
            </tbody>
            <tfoot>
              <tr className="records-calculation-row">
                <td className="records-cell records-sticky-cell">
                  <span className="records-footer-value records-calculation-label">
                    <span className="records-calculation-number">{rows.length}</span> count
                  </span>
                </td>
                <td className="records-cell">
                  <button
                    type="button"
                    className="records-add-calculation disabled:pointer-events-none disabled:opacity-50"
                    onClick={onAddCalculation}
                    disabled={!onAddCalculation}
                    title={
                      onAddCalculation ? "Add calculation" : "Calculation setup is unavailable"
                    }
                  >
                    <Icon size={15}>
                      <path d="M12 5v14M5 12h14" />
                    </Icon>
                    Add calculation
                  </button>
                </td>
                <td className="records-cell records-muted">
                  <span className="records-footer-value">—</span>
                </td>
                <td className="records-cell">
                  <span className="records-footer-value records-average">
                    <span
                      className="records-strength-dot"
                      style={{ background: "var(--orange)" }}
                    />
                    {Math.round(
                      (rows.reduce((sum, row) => sum + STRENGTH[row.strength].rank, 0) /
                        rows.length /
                        3) *
                        100,
                    )}
                    % average
                  </span>
                </td>
                <td className="records-cell">
                  <span className="records-footer-value records-muted">
                    {rows.filter((row) => row.website).length} links
                  </span>
                </td>
                {aiAdded && (
                  <td className="records-cell records-muted">
                    <span className="records-footer-value">
                      {aiDone ? `${rows.length} filled` : "—"}
                    </span>
                  </td>
                )}
                <td className="records-cell" />
              </tr>
            </tfoot>
          </table>
        </div>
      </div>

      {/* ── property configuration popover ─────────────────── */}
      {prop && meta
        ? createPortal(
            <BeautifulUIPortalRoot
              ref={propPopoverRef}
              data-recpop
              role="dialog"
              aria-label={`${prop.col} property settings`}
              onKeyDown={(event) => {
                if (event.key !== "Escape") return;
                event.preventDefault();
                event.stopPropagation();
                closePropertyPopover(true);
              }}
              className="fixed z-50 max-h-[calc(100vh-24px)] w-[calc(100vw-24px)] max-w-[320px] overflow-y-auto rounded-[var(--records-container-radius)] bg-[var(--surface)] px-3 pt-3 pb-1.5 shadow-surface-3"
              style={{
                ...shapeStyle,
                top: prop.y,
                left: prop.x,
                maxHeight: `calc(100vh - ${prop.y + POPOVER_VIEWPORT_GUTTER}px)`,
                animation: "pop-in 160ms cubic-bezier(0.23,1,0.32,1) both",
                transformOrigin: "top left",
              }}
            >
              <div className="pb-2 text-[14px] font-medium text-[var(--ink)]">{prop.col}</div>

              <ConfigRow label="Type">
                <button
                  type="button"
                  aria-haspopup="menu"
                  aria-expanded={configMenu === "type"}
                  onClick={() => setConfigMenu((current) => (current === "type" ? null : "type"))}
                  className="flex items-center gap-1.5 rounded-[var(--records-control-radius)] px-1.5 py-1 text-[13px] font-medium text-[var(--ink)] transition-colors duration-80 hover:bg-[var(--hover)]"
                >
                  <span className="text-[var(--ink-2)]">
                    <Icon size={14}>{TYPE_GLYPHS[meta.type] ?? TYPE_GLYPHS.Text}</Icon>
                  </span>
                  {meta.type}
                  <span className="text-[var(--ink-3)]">
                    <Icon size={12} strokeWidth={2.2}>
                      <path d="M9 6l6 6-6 6" />
                    </Icon>
                  </span>
                </button>
                {configMenu === "type" && (
                  <ConfigPicker
                    label="Property type"
                    selected={meta.type}
                    options={NEW_PROPERTY_TYPES.map((type) => ({
                      label: type,
                      icon: <Icon size={15}>{TYPE_GLYPHS[type]}</Icon>,
                    }))}
                    onSelect={(type) => {
                      setColumnOverrides((current) => ({
                        ...current,
                        [prop.col]: { ...current[prop.col], type },
                      }));
                      setConfigMenu(null);
                    }}
                  />
                )}
              </ConfigRow>
              <ConfigRow label="Tool">
                <button
                  type="button"
                  aria-haspopup="menu"
                  aria-expanded={configMenu === "tool"}
                  onClick={() => setConfigMenu((current) => (current === "tool" ? null : "tool"))}
                  className="flex items-center gap-1.5 rounded-[var(--records-control-radius)] px-1.5 py-1 text-[13px] font-medium text-[var(--ink)] transition-colors duration-80 hover:bg-[var(--hover)]"
                >
                  <span
                    className={
                      meta.toolKind === "model"
                        ? "text-[var(--bui-focus-ink)]"
                        : "text-[var(--ink-2)]"
                    }
                  >
                    {meta.toolKind === "model" ? (
                      <svg
                        width="14"
                        height="14"
                        viewBox="0 0 24 24"
                        fill="currentColor"
                        aria-hidden
                      >
                        {TOOL_GLYPHS.model}
                      </svg>
                    ) : (
                      <Icon size={14}>{TOOL_GLYPHS[meta.toolKind]}</Icon>
                    )}
                  </span>
                  {meta.tool}
                  <span className="text-[var(--ink-3)]">
                    <Icon size={12} strokeWidth={2.2}>
                      <path d="M9 6l6 6-6 6" />
                    </Icon>
                  </span>
                </button>
                {configMenu === "tool" && (
                  <ConfigPicker
                    label="Model"
                    selected={meta.tool}
                    options={MODEL_OPTIONS.map((model) => ({
                      label: model,
                      icon: (
                        <svg
                          width="14"
                          height="14"
                          viewBox="0 0 24 24"
                          fill="currentColor"
                          aria-hidden
                        >
                          {TOOL_GLYPHS.model}
                        </svg>
                      ),
                    }))}
                    onSelect={(tool) => {
                      setColumnOverrides((current) => ({
                        ...current,
                        [prop.col]: { ...current[prop.col], tool, toolKind: "model" },
                      }));
                      setConfigMenu(null);
                    }}
                  />
                )}
              </ConfigRow>
              <ConfigRow label="Grounding">
                <span className="flex items-center gap-2">
                  <SettingSwitch
                    label="Grounding"
                    checked={grounding}
                    onToggle={() => setGrounding((current) => !current)}
                  />
                  <button
                    type="button"
                    aria-label="About grounding"
                    aria-expanded={groundingHelpOpen}
                    onClick={() => setGroundingHelpOpen((open) => !open)}
                    className="flex size-6 items-center justify-center rounded-[var(--records-control-radius)] text-[var(--ink-3)] transition-colors duration-80 hover:bg-[var(--hover)] hover:text-[var(--ink)]"
                  >
                    <Icon size={13}>
                      <g>
                        <circle cx="12" cy="12" r="9" />
                        <path d="M12 8h.01M11 12h1v4h1" />
                      </g>
                    </Icon>
                  </button>
                </span>
                {groundingHelpOpen && (
                  <Elevated
                    offset={2}
                    shadowLevel={3}
                    className="absolute right-0 top-[30px] z-30 w-[230px] rounded-[var(--records-container-radius)] px-3 py-2.5 text-[12px] leading-relaxed"
                    style={{ color: "var(--tooltip-fg)" }}
                    role="status"
                  >
                    Grounding lets the model verify generated values against connected sources.
                  </Elevated>
                )}
              </ConfigRow>
              <ConfigRow label="Inputs">
                <button
                  type="button"
                  aria-haspopup="menu"
                  aria-expanded={configMenu === "inputs"}
                  onClick={() =>
                    setConfigMenu((current) => (current === "inputs" ? null : "inputs"))
                  }
                  className="flex max-w-[220px] items-center gap-1.5 rounded-[var(--records-control-radius)] px-1.5 py-1 text-[13px] text-[var(--ink-2)] transition-colors duration-80 hover:bg-[var(--hover)] hover:text-[var(--ink)]"
                >
                  {selectedInputs.length ? (
                    <span className="flex min-w-0 items-center gap-1">
                      {selectedInputs.slice(0, 2).map((input) => (
                        <span
                          key={input}
                          className="max-w-[92px] truncate rounded-[var(--records-chip-radius)] bg-[var(--bui-focus-tint)] px-1.5 py-0.5 text-[12px] font-medium text-[var(--bui-focus-ink)]"
                        >
                          {input}
                        </span>
                      ))}
                      {selectedInputs.length > 2 && (
                        <span className="text-[11px] font-medium text-[var(--ink-3)]">
                          +{selectedInputs.length - 2}
                        </span>
                      )}
                    </span>
                  ) : (
                    <span>Select inputs</span>
                  )}
                  <span className="shrink-0 text-[var(--ink-3)]">
                    <Icon size={12} strokeWidth={2.2}>
                      <path d="M9 6l6 6-6 6" />
                    </Icon>
                  </span>
                </button>
                {configMenu === "inputs" && (
                  <InputPicker
                    selected={selectedInputs}
                    options={INPUT_OPTIONS.filter((input) => input !== prop.col)}
                    onToggle={(input) => {
                      setInputSelections((current) => {
                        const existing = current[prop.col] ?? (meta.inputs ? [meta.inputs] : []);
                        const next = existing.includes(input)
                          ? existing.filter((item) => item !== input)
                          : [...existing, input];
                        return { ...current, [prop.col]: next };
                      });
                    }}
                  />
                )}
              </ConfigRow>

              {/* prompt — @-mention chips inline */}
              <div
                contentEditable
                suppressContentEditableWarning
                role="textbox"
                aria-label={`${prop.col} calculation prompt`}
                aria-multiline="true"
                spellCheck
                className="mt-2 min-h-[88px] cursor-text appearance-none border-0 rounded-[var(--records-inset-radius)] bg-[var(--inset)] p-3 text-[13px] leading-relaxed shadow-[var(--shadow-hairline)] outline-none transition-[background-color] duration-160 focus:bg-[var(--surface)]"
              >
                {meta.prompt ? (
                  <span className="text-[var(--ink)]">
                    {meta.prompt.before}
                    {meta.prompt.chip && (
                      <span
                        contentEditable={false}
                        className="rounded-[var(--records-chip-radius)] bg-[var(--bui-focus-tint)] px-1.5 py-0.5 text-[12px] font-medium text-[var(--bui-focus-ink)]"
                      >
                        {meta.prompt.chip}
                      </span>
                    )}
                    {meta.prompt.after}
                  </span>
                ) : (
                  <span className="text-[var(--ink-3)]">
                    Set a prompt (press @ to mention an input)
                  </span>
                )}
              </div>

              <CalculateButton
                disabled={!!calc}
                onClick={() => {
                  setCalc({ col: prop.col, resolved: 0 });
                  setProp(null);
                }}
              />

              <GlideMenu
                className="mt-3 flex flex-col gap-0.5 border-t border-[var(--line)] pt-2"
                highlightClassName="-inset-x-1.5 rounded-[var(--records-menu-item-radius)] bg-[var(--hover)]"
              >
                <button
                  data-menu-row
                  type="button"
                  aria-pressed={pinnedColumns.has(prop.col)}
                  onClick={() =>
                    setPinnedColumns((current) => {
                      const next = new Set(current);
                      if (next.has(prop.col)) next.delete(prop.col);
                      else next.add(prop.col);
                      return next;
                    })
                  }
                  className="relative z-10 -mx-1.5 flex h-8 items-center gap-2.5 rounded-[var(--records-menu-item-radius)] px-1.5 text-left text-[13px] leading-none text-[var(--ink)] transition-transform duration-160 active:scale-[0.98]"
                >
                  <span
                    className={
                      pinnedColumns.has(prop.col)
                        ? "text-[var(--bui-focus-ink)]"
                        : "text-[var(--ink-2)]"
                    }
                  >
                    <Icon size={15}>
                      <path d="M12 17v5M8 3h8l-1 7 3 3H6l3-3-1-7z" />
                    </Icon>
                  </span>
                  {pinnedColumns.has(prop.col) ? "Unpin" : "Pin"}
                </button>
                <button
                  data-menu-row
                  type="button"
                  aria-expanded={moreSettingsOpen}
                  onClick={() => setMoreSettingsOpen((open) => !open)}
                  className="relative z-10 -mx-1.5 flex h-8 items-center gap-2.5 rounded-[var(--records-menu-item-radius)] px-1.5 text-left text-[13px] leading-none text-[var(--ink)] transition-transform duration-160 active:scale-[0.98]"
                >
